import * as React from "react";

import { AnimatedCollapse } from "./animated-collapse";
import { Icon, type IconName } from "./icon";
import { MiddleTruncate } from "./middle-truncate";

import styles from "./data.module.css";

export interface FileTreeNode {
  id: string;
  name: string;
  type?: "file" | "folder";
  children?: readonly FileTreeNode[];
  meta?: React.ReactNode;
  icon?: IconName;
  disabled?: boolean;
  label?: string;
}
export interface FileTreeProps {
  items: readonly FileTreeNode[];
  label: string;
  expanded?: readonly string[];
  defaultExpanded?: readonly string[];
  onExpandedChange?: (ids: string[]) => void;
  selected?: string | null;
  defaultSelected?: string | null;
  onSelect?: (id: string, node: FileTreeNode) => void;
  selectable?: "all" | "files" | "folders" | "none";
  foldersOnly?: boolean;
  size?: "sm" | "md";
  maxHeight?: number;
  truncate?: "middle" | "end";
  empty?: React.ReactNode;
}
const folder = (node: FileTreeNode) =>
  node.type ? node.type === "folder" : node.children !== undefined;
function selectedAncestors(
  nodes: readonly FileTreeNode[],
  selected: string | null
): string[] | null {
  if (selected === null) return [];
  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index];
    if (!node) return null;
    if (node.id === selected) return [];
    const childPath = selectedAncestors(node.children ?? [], selected);
    if (childPath) return [node.id, ...childPath];
  }
  return null;
}
export function FileTree({
  items,
  label,
  expanded,
  defaultExpanded = [],
  onExpandedChange,
  selected,
  defaultSelected = null,
  onSelect,
  selectable = "all",
  foldersOnly = false,
  size = "md",
  maxHeight,
  truncate = "middle",
  empty = "No files"
}: FileTreeProps) {
  const [ownExpanded, setOwnExpanded] = React.useState<readonly string[]>(() => [
    ...new Set([
      ...defaultExpanded,
      ...(selectedAncestors(items, selected ?? defaultSelected) ?? [])
    ])
  ]);
  const [ownSelected, setOwnSelected] = React.useState<string | null>(defaultSelected);
  const [focused, setFocused] = React.useState<string | null>(null);
  const open = expanded ?? ownExpanded;
  const current = selected === undefined ? ownSelected : selected;
  const revealedSelection = React.useRef<string | null>(undefined);
  React.useEffect(() => {
    if (revealedSelection.current === current) return;
    const ancestors = selectedAncestors(items, current);
    if (!ancestors) return;
    revealedSelection.current = current;
    const next = [...new Set([...open, ...ancestors])];
    if (next.length !== open.length) {
      if (expanded === undefined) setOwnExpanded(next);
      onExpandedChange?.(next);
    }
  }, [current, items, open, expanded, onExpandedChange]);
  const targets = React.useRef(new Map<string, HTMLLIElement>());
  const tree = React.useRef<HTMLUListElement>(null);
  const focusWithin = React.useRef(false);
  const search = React.useRef({ text: "", time: 0 });
  const uid = React.useId();
  const visible: { node: FileTreeNode; parent: string | null }[] = [];
  const flatten = (nodes: readonly FileTreeNode[], parent: string | null) => {
    nodes.forEach((node) => {
      if (foldersOnly && !folder(node)) return;
      visible.push({ node, parent });
      if (open.includes(node.id)) flatten(node.children ?? [], node.id);
    });
  };
  flatten(items, null);
  const first = visible[0]?.node.id;
  const focusId =
    focused && visible.some(({ node }) => node.id === focused)
      ? focused
      : current && visible.some(({ node }) => node.id === current)
        ? current
        : first;
  const expand = (id: string, value: boolean) => {
    const next = value ? [...open.filter((x) => x !== id), id] : open.filter((x) => x !== id);
    if (expanded === undefined) setOwnExpanded(next);
    onExpandedChange?.(next);
  };
  const focus = (id: string | undefined) => {
    if (id) {
      setFocused(id);
      targets.current.get(id)?.focus();
    }
  };
  React.useLayoutEffect(() => {
    if (!focused || visible.some(({ node }) => node.id === focused)) return;
    const parents = new Map<string, string | null>();
    const visit = (nodes: readonly FileTreeNode[], parent: string | null) =>
      nodes.forEach((node) => {
        parents.set(node.id, parent);
        visit(node.children ?? [], node.id);
      });
    visit(items, null);
    const visibleIds = new Set(visible.map(({ node }) => node.id));
    let next = parents.get(focused);
    while (next && !visibleIds.has(next)) next = parents.get(next);
    const target = next ?? first;
    if (target) {
      setFocused(target);
      if (focusWithin.current) targets.current.get(target)?.focus();
    }
  }, [focused, open, items, foldersOnly]);
  const canSelect = (node: FileTreeNode) =>
    !node.disabled &&
    (selectable === "all" ||
      (selectable === "files" && !folder(node)) ||
      (selectable === "folders" && folder(node)));
  const pick = (node: FileTreeNode) => {
    if (canSelect(node)) {
      if (selected === undefined) setOwnSelected(node.id);
      onSelect?.(node.id, node);
    } else if (folder(node) && !node.disabled) expand(node.id, !open.includes(node.id));
  };
  const onKey = (event: React.KeyboardEvent<HTMLLIElement>, node: FileTreeNode) => {
    if (event.target !== event.currentTarget) return;
    const index = visible.findIndex((entry) => entry.node.id === node.id);
    const parent = visible[index]?.parent;
    let handled = true;
    switch (event.key) {
      case "ArrowDown":
        focus(visible[Math.min(visible.length - 1, index + 1)]?.node.id);
        break;
      case "ArrowUp":
        focus(visible[Math.max(0, index - 1)]?.node.id);
        break;
      case "Home":
        focus(visible[0]?.node.id);
        break;
      case "End":
        focus(visible[visible.length - 1]?.node.id);
        break;
      case "ArrowRight":
        if (folder(node) && !node.disabled) {
          if (!open.includes(node.id)) expand(node.id, true);
          else
            focus(visible[index + 1]?.parent === node.id ? visible[index + 1]?.node.id : undefined);
        }
        break;
      case "ArrowLeft":
        if (folder(node) && open.includes(node.id)) expand(node.id, false);
        else focus(parent ?? undefined);
        break;
      case "Enter":
      case " ":
        pick(node);
        break;
      default:
        handled = false;
        if (
          event.key.length === 1 &&
          !event.ctrlKey &&
          !event.metaKey &&
          !event.altKey &&
          !event.nativeEvent.isComposing
        ) {
          const now = Date.now();
          search.current = {
            text: now - search.current.time < 500 ? search.current.text + event.key : event.key,
            time: now
          };
          const rest = [...visible.slice(index + 1), ...visible.slice(0, index + 1)];
          focus(
            rest.find((entry) =>
              entry.node.name.toLowerCase().startsWith(search.current.text.toLowerCase())
            )?.node.id
          );
        }
    }
    if (handled) {
      event.preventDefault();
      event.stopPropagation();
    }
  };
  const render = (nodes: readonly FileTreeNode[], level: number): React.ReactNode =>
    nodes
      .filter((node) => !foldersOnly || folder(node))
      .map((node, index, shown) => (
        <li
          key={node.id}
          ref={(element) => {
            if (element) targets.current.set(node.id, element);
            else targets.current.delete(node.id);
          }}
          role="treeitem"
          aria-level={level}
          aria-setsize={shown.length}
          aria-posinset={index + 1}
          aria-expanded={folder(node) ? open.includes(node.id) : undefined}
          aria-selected={current === node.id}
          aria-disabled={node.disabled || undefined}
          aria-label={node.label ?? node.name}
          tabIndex={focusId === node.id ? 0 : -1}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setFocused(node.id);
          }}
          onKeyDown={(event) => onKey(event, node)}
          onClick={(event) => {
            event.stopPropagation();
            focus(node.id);
            pick(node);
          }}
        >
          <div
            className={styles.treeRow}
            data-size={size}
            data-selected={current === node.id}
            aria-disabled={node.disabled || undefined}
          >
            {folder(node) && (
              <button
                type="button"
                tabIndex={-1}
                disabled={node.disabled}
                aria-label={`${open.includes(node.id) ? "Collapse" : "Expand"} ${node.name}`}
                aria-expanded={open.includes(node.id)}
                aria-controls={`${uid}-${node.id}`}
                onMouseDown={(event) => event.preventDefault()}
                onClick={(event) => {
                  event.stopPropagation();
                  focus(node.id);
                  expand(node.id, !open.includes(node.id));
                }}
              >
                {" "}
                {open.includes(node.id) ? "▾" : "▸"}{" "}
              </button>
            )}
            <Icon
              name={
                node.icon ??
                (folder(node) ? (open.includes(node.id) ? "folder-open" : "folder") : "file")
              }
            />
            <span className={styles.treeName} title={node.name}>
              {truncate === "middle" ? <MiddleTruncate text={node.name} keepEnd={8} /> : node.name}
            </span>
            {node.meta && <span className={styles.treeMeta}>{node.meta}</span>}
          </div>
          {folder(node) && (
            <AnimatedCollapse open={open.includes(node.id)} lazy>
              <ul role="group" id={`${uid}-${node.id}`}>
                {render(node.children ?? [], level + 1)}
              </ul>
            </AnimatedCollapse>
          )}
        </li>
      ));
  return visible.length ? (
    <ul
      ref={tree}
      role="tree"
      aria-label={label}
      data-slot="file-tree"
      data-size={size}
      data-scroll-fade="both"
      className={styles.tree}
      style={{ maxHeight }}
      onFocusCapture={() => {
        focusWithin.current = true;
      }}
      onBlurCapture={(event) => {
        if (
          event.relatedTarget instanceof Node &&
          !event.currentTarget.contains(event.relatedTarget)
        )
          focusWithin.current = false;
      }}
    >
      {render(items, 1)}
    </ul>
  ) : (
    <div className={styles.empty}>{empty}</div>
  );
}

.gridShell,
.tableShell,
.listShell {
  color: var(--v4-ink);
}
.gridScroll,
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.tableScroll {
  border-radius: 0;
  overflow: auto;
  position: relative;
}
.tableScroll {
  scroll-padding-block: var(--v4-focus-clearance);
}
.gridScroll {
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridScroll {
  font-family: var(--v4-type-mono-font-family);
  font-size: var(--v4-type-mono-font-size);
  line-height: var(--v4-type-mono-line-height);
  font-weight: var(--v4-type-mono-font-weight);
  letter-spacing: var(--v4-type-mono-letter-spacing);
}
.tree:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridScroll[aria-activedescendant]:focus-visible {
  outline: none;
}
.gridRow,
.gridHead {
  display: grid;
  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridRow[data-last] {
  border-bottom-color: transparent;
}
/* With a footer the grid is a framed shell: the borderless tint frame holds the inset
   grid on top and the footer below, so there is exactly one edge at the bottom. */
.gridShell[data-footer] {
  --v4-frame-pad: var(--v4-space-3);
  padding: var(--v4-frame-pad) var(--v4-frame-pad) 0;
  background: var(--v4-tint);
  border-radius: 0;
}
.gridShell[data-footer] > .gridScroll {
  border-radius: 0;
  box-shadow: var(--v4-shadow-raised);
}
.gridShell[data-footer] > .status,
.gridShell[data-footer] > .actions {
  padding-inline: var(--v4-space-8);
}
.gridFooter {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-space-40);
  padding: var(--v4-space-4) var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-variant-numeric: tabular-nums;
}
.gridAddHeader {
  display: flex;
  align-items: center;
  padding-inline: var(--v4-space-4);
}
.gridAddForm {
  display: grid;
  gap: var(--v4-space-6);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.gridAddCheck {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-4);
}
.gridAddActions {
  display: flex;
  justify-content: flex-end;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-8);
}
.gridKey {
  flex: none;
  color: var(--v4-muted);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--v4-paper);
  min-height: var(--v4-size-control-sm);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  padding: 0 var(--v4-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-6);
  padding-inline: var(--v4-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  color: var(--v4-ink);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridSort[data-active] {
  color: var(--v4-ink);
}
.gridSort:not([data-active]) {
  opacity: 0;
}
.gridHeader:is(:hover, :focus-within) > .gridSort {
  opacity: 1;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--v4-surface);
  padding: var(--v4-space-6) var(--v4-space-8);
  min-width: var(--v4-space-40);
  text-align: right;
  color: var(--v4-faint);
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
}
.gridCell {
  padding: var(--v4-space-6) var(--v4-space-8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  position: relative;
}
:global(.v4) {
  --overlay-hover: var(--v4-hover-mix);
  --overlay-press: var(--v4-press-mix);
}
.gridRow:hover > .gridCell:not([data-selected], [data-dirty]) {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), transparent);
}
.gridCell[data-selected] {
  background: var(--v4-accent-wash);
}
.gridNull {
  color: var(--v4-faint);
  font-style: italic;
}
.gridCell[data-dirty] {
  background: var(--v4-warn-wash);
}
.gridCell[data-active] {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridCell textarea {
  font: inherit;
  color: inherit;
  background: var(--v4-surface);
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  box-sizing: border-box;
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
  padding: var(--v4-space-6) var(--v4-space-8);
  line-height: inherit;
  white-space: pre;
  overflow: hidden;
}
.gridCell textarea[aria-invalid="true"] {
  outline-color: var(--v4-bad);
}
.resize {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * (var(--v4-space-12) + var(--v4-size-control-border)));
  z-index: 1;
  width: var(--v4-space-24);
  cursor: col-resize;
  touch-action: none;
}
.resize::after {
  content: "";
  position: absolute;
  inset-block: 0;
  left: calc(50% - var(--v4-size-control-border));
  width: var(--v4-size-control-border);
  background: transparent;
  pointer-events: none;
  transition: background-color var(--v4-duration-fast) var(--v4-ease-fade);
}
.resize:hover::after {
  background: var(--v4-control);
}
.resize:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.status {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
  padding: var(--v4-space-8) 0 0;
  overflow-wrap: anywhere;
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  flex-wrap: wrap;
  padding: var(--v4-space-12) 0 0;
}
.actions [role="alert"] {
  color: var(--v4-bad);
}
.empty {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  padding: var(--v4-space-surface-inset-sm);
  color: var(--v4-muted);
}
.editor {
  display: grid;
  gap: var(--v4-space-8);
  min-width: 0;
  color: var(--v4-ink);
}
.label {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-field-label-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
}
.secret {
  --v4-nested-action-height: var(--v4-size-nested-default);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--v4-space-control-slot-gap);
  padding: var(--v4-space-control-slot-inset);
  padding-inline-start: var(--v4-space-control-inline);
  min-height: var(--v4-size-control-default);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: 0;
  background: var(--v4-tint);
  min-width: 0;
}
.machine {
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  overflow-wrap: anywhere;
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}
.editorInput {
  display: block;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  border-radius: 0;
  background: var(--v4-surface);
  color: var(--v4-ink);
  border: var(--v4-size-control-border) solid var(--v4-control);
  min-height: var(--v4-size-control-default);
  max-height: calc(12 * var(--v4-type-body-line-height));
  padding: calc(
      (var(--v4-size-control-default) - var(--v4-type-body-line-height)) / 2 -
        var(--v4-size-control-border)
    )
    var(--v4-space-control-inline);
  width: 100%;
  resize: none;
  field-sizing: content;
  transition-property: border-color, box-shadow;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.editorInput:focus-visible {
  outline: none;
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-glow) var(--v4-focus-ring);
}
.editorInput::placeholder {
  color: var(--v4-muted);
}
.editorSlot {
  flex: none;
  width: var(--v4-nested-action-height);
  height: var(--v4-nested-action-height);
}
.editorActions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--v4-space-8);
}
.editorError {
  color: var(--v4-bad);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  overflow-wrap: anywhere;
}
.copy {
  --v4-nested-action-height: var(--v4-size-nested-sm);
